package vn.worldcomesalive.generation.v2;
import java.util.*;
/** Reject spatial/economic failures; diagnostics persist with the accepted plan for reproducible QA. */
public final class GenerationValidation {
    public static void validate(SettlementPlan p,GenerationCatalog data){p.failures.clear();int beds=p.buildings.stream().mapToInt(b->data.buildings.get(b.program()).beds()).sum(),food=p.fields.stream().filter(f->f.kind().equals("CROP")).mapToInt(SettlementPlan.Field::capacity).sum();if(beds!=p.program.populationTarget())p.failures.add("Housing capacity does not match economic population");if(food<p.program.foodCapacity())p.failures.add("Insufficient agriculture");Set<String> connected=new HashSet<>();connected.add("core");boolean changed;do{changed=false;for(var r:p.roads)if(connected.contains(r.from())||connected.contains(r.to())){changed|=connected.add(r.from());changed|=connected.add(r.to());}}while(changed);for(var d:p.districts)if(!connected.contains(d.id()))p.failures.add("Disconnected district "+d.id());for(var l:p.lots)if(!connected.contains(l.id()))p.failures.add("Inaccessible property "+l.id());for(int i=0;i<p.lots.size();i++)for(int j=i+1;j<p.lots.size();j++)if(p.lots.get(i).boundary().overlaps(p.lots.get(j).boundary()))p.failures.add("Overlapping lots");for(var b:p.buildings)for(var road:p.roads)if(!road.from().equals(b.lot())&&TerrainRouter.crosses(b.bounds(),road,1))p.failures.add("Road/building collision "+b.id());long silhouettes=p.buildings.stream().filter(b->data.buildings.get(b.program()).type().equals("cottage")).map(SettlementPlan.Building::program).distinct().count();if(silhouettes<5)p.failures.add("Insufficient residential silhouettes");p.quality.put("housingCapacity",(double)beds);p.quality.put("foodCapacity",(double)food);p.quality.put("agriculturalArea",(double)p.fields.stream().mapToInt(f->f.boundary().area()).sum());p.quality.put("buildingArea",(double)p.buildings.stream().mapToInt(b->b.bounds().area()).sum());p.quality.put("residentialSilhouettes",(double)silhouettes);p.quality.put("roadClasses",(double)p.roads.stream().map(SettlementPlan.Road::kind).distinct().count());}
    private GenerationValidation(){}
}
